from pathlib import Path
from datetime import datetime
p=Path(__file__).parent;d=json.loads((p/'rotation_results.json').read_text())
for r in d['results']:
 if r['id']=='near':r['name']='固定本周五（周五顺延）'
 realized=0;curve=[dict(time=d['start']+'T10:00:00-04:00',value=0)];required=0;peak=0;drawdown=0
 for tr in r['trades']:
  required=max(required,tr['entry']['value']-realized)
  curve.append(dict(time=tr['entry']['time'],value=realized))
  for point in tr['curve']:curve.append(dict(time=point['time'],value=realized+point['pnl']))
  curve.append(dict(time=tr['exit']['time'],value=realized+tr['gross']))
  if tr['status']!='仍持仓估值':realized+=tr['gross']
 curve.append(dict(time=d['end']+'T16:00:00-04:00',value=r['stats']['total']))
 curve.sort(key=lambda x:x['time'])
 for point in curve:peak=max(peak,point['value']);drawdown=max(drawdown,peak-point['value'])
 r['equity']=curve;r['stats']['required_cash']=required;r['stats']['observed_drawdown']=drawdown
best=max(d['results'],key=lambda r:r['stats']['total']);d['best']=best['id']
css='''*{box-sizing:border-box}body{margin:0;background:#0e121b;color:#e7edf7;font:14px/1.8 system-ui,-apple-system,"PingFang SC",sans-serif;color-scheme:dark}main{max-width:1540px;margin:auto;padding:32px 24px}h1{font-size:30px}h2{font-size:21px}section{background:#171e2c;border:1px solid #2b3546;border-radius:14px;padding:24px;margin:22px 0}a{color:#79b7ff}.muted,small{color:#9cabbe}.note{border-left:3px solid #ffd166;padding:12px;background:#ffd16609}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#202a3b;padding:16px;border-radius:10px}.card strong{display:block;font-size:24px;color:#ffd166}.scroll{overflow:auto;max-height:660px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #2b3546;padding:10px;text-align:right;white-space:nowrap}th{position:sticky;top:0;background:#202a3b;color:#a9bbd3}td:first-child,th:first-child{text-align:left}.wrap{white-space:normal;min-width:220px;max-width:400px}.pos{color:#58dcc0}.neg{color:#fb8495}select{padding:9px;background:#202c3e;color:#e7edf7;border:1px solid #3b4960;border-radius:6px}.toolbar{display:flex;gap:20px;flex-wrap:wrap;margin:15px 0}.chart{position:relative}canvas{display:block;width:100%;height:420px}.tip{display:none;position:absolute;pointer-events:none;background:#080e18f5;border:1px solid #738398;border-radius:9px;padding:12px;z-index:2;font-size:12px}.legend{display:flex;gap:16px;flex-wrap:wrap}summary{cursor:pointer;color:#79b7ff}code{color:#ffd166}@media(max-width:800px){main{padding:14px}.cards{grid-template-columns:1fr 1fr}section{padding:15px}h1{font-size:25px}}'''
body='''<main><div class="muted">SKHY · 报告4 · 单仓轮动研究</div><h1>平仓后重新开仓：本周五还是下周五？</h1><p id="asof"></p><div id="cards" class="cards"></div>
<section><h2>这次比较什么</h2><p>每次仅持有<strong>1张Call＋1张Put</strong>，同到期日、同行权价。旧组合卖出后，在下一个10分钟检查点重新选择接近平值的组合，不等到下一周五；需要时追加资金。开仓总权利金／100股市值≤12%，过贵则空仓至下一交易日10:00再评估。</p><p>六种期限规则共用同一套平仓规则：股价相对本次入场上涨时，组合盈利目标150%；下跌时10%。只有进入<strong>所持合约到期周</strong>后，周三目标变为112.5%／7.5%，周四75%／5%，到期周五37.5%／2.5%。买下周五合约时，本周三、周四不提前降低目标。每次重开仓，成本基准和股价方向基准全部重置。</p><p class="note">平仓参数沿用报告3，冻结后只比较期限选择。仍是历史样本内研究：原平仓参数也曾用这段历史选过，不能把本报告当作独立样本外验证。“最优”仅指下面六个已测试方案在当前区间的最高合计毛收益。</p><div id="conclusion"></div></section>
<section><h2>从报告3最近一次平仓出发：重新开仓选哪天？</h2><div id="example"></div></section>
<section><h2>不同期限选择规则：同一时间区间对比</h2><p class="muted">排名按已实现毛收益＋期末持仓估值。把仍持仓亏损也计入，避免只统计已平仓盈利。所有方案都列出已实现和未实现部分；不扣费用、不计算年化。</p><div class="scroll" id="comparison"></div><p class="muted">累计权利金支出是多次周转之和，不等于初始资金。“最低现金需求”按本回测顺序计算，盈利可再投入，亏损可追加；不含费用。最大回撤来自可用估值观察点，行情缺失期间可能低估实际回撤。</p></section>
<section><h2>累计毛收益随时间变化</h2><div class="legend" id="legend"></div><div class="chart"><canvas id="equity"></canvas><div class="tip" id="equitytip"></div></div><p class="muted">曲线包含持仓估值，卖出后收益延续至下次开仓。鼠标查看各方案最近一次有效观察值及时间；连线仅连接离散数据，不代表中间每一刻均有成交。</p></section>
<section><h2>逐笔轮动：何时买、何时卖、当时股价和盈亏</h2><div class="toolbar"><label>方案 <select id="policy"></select></label></div><div class="scroll" id="ledger"></div><p class="muted">时间均为美东。股价取买卖共同成交分钟的股票开盘价；到期取日收盘价。期权报价每股计，每张乘100。每一行是一次完整开仓，不再按原来的周五周期合并。</p></section>
<section><h2>每笔持仓：组合毛收益与股票涨跌幅</h2><div class="toolbar"><label>交易 <select id="trade"></select></label></div><div id="tradeinfo"></div><div class="legend"><span style="color:#58dcc0">绿色：组合毛收益$ · 左轴</span><span style="color:#54afff">蓝色：股票涨跌% · 右轴</span></div><div class="chart"><canvas id="tradechart"></canvas><div class="tip" id="tradetip"></div></div></section>
<section><h2>轮空原因：费用过高还是行情不足</h2><div id="quality"></div><p class="muted">行情不足或找不到共同成交分钟不等于市场完全无法交易，只表示当前成交数据无法支持本回测的执行假设。真实可成交性仍需买卖盘验证。</p></section>
<section><h2>开仓时的期限选择与轮空明细</h2><p>这里显示做决定时已经发生的成交价、剩余自然日和费用比。候选行权价按最初评估时已完成的股票分钟价选择；若缺报价，固定该候选合约等待当天后续检查点。费用超过上限则当日轮空，避免全天不断追价。</p><div class="scroll" id="decisions"></div></section>
<section><h2>“多花一点钱，多买几天”怎么量化</h2><p>例如周二，本周五剩3天、下周五剩10天。如果近月组合花$1,000、远月花$1,250，则远月贵25%，多买7天。25%档和50%档会选远月，10%档选近月；前提是远月仍满足12%费用上限。这是规则示例，不是本次历史成交。</p><p>另一档比较 <strong>（Call＋Put报价）÷股价÷√剩余自然日</strong>，数值低者优先。这一档不设固定50%加价帽：例如近端只剩约1天、远端约8天时，即使远端贵一倍以上也可能被选中，但总权利金仍须≤股价的12%。同样股价下，上述远月的指标是近月的1.25×√(3/10)≈68.5%。这是近似平值、波动随时间平方根缩放的启发式指标，不是真实隐含波动率，也不保证未来收益；不同到期日可能包含不同事件风险。</p><p>不直接把权利金除以天数作为唯一依据：时间价值衰减不是线性的，临近到期的平值期权通常衰减更快。更长到期并不意味着没有Theta损耗。参考 <a href="https://www.optionseducation.org/advancedconcepts/theta">OIC：Theta</a> 与 <a href="https://prd-web.optionseducation.org/strategies/all-strategies/long-straddle">OIC：Long Straddle</a>。</p></section>
<section><h2>执行规则与数据边界</h2><p>首次从7月31日10:00评估。每次平仓后，下一个10分钟整点且不早于10:00再评估；15:30后不新开仓，顺延至下一交易日10:00。周一至周四比较本周五和下周五；周五不买当天到期合约，只有下周五候选。固定本周方案在周五也使用下周五；固定下周方案平日不回退到本周。</p><p>候选成交价只取已完成的当日分钟，两腿价格年龄≤10分钟；历史合约列表按当日查询，标准100股合约，最接近平值行权价，相同距离取较低行权价。若灵活方案只有一个期限有合格报价，就只考虑该期限；这不代表另一期限不存在。表中报价缺失不会被当作0。</p><p>开仓、平仓都在决策至少一分钟之后，寻找股票和两腿的共同成交分钟，以分钟开盘价模拟。开仓额外要求当时权利金／股价≤12%，否则继续等待当天15:30前的可用分钟；当日无合格分钟则轮空。平仓若无后续共同分钟，保留到期结算或期末估值。价格源是实际历史成交，不是可执行买卖盘，不保证实盘按此价格成交。</p><p>平仓信号每10分钟检查；期末持仓用当天两腿最后成交价估值并披露价格年龄。期权价格已经包含时间价值，不另扣Theta。股价与两腿并非同秒成交；额外轮动也会增加实际佣金与价差，本报告仍遵循只显示毛收益的口径。</p><p><a href="rotation_results.json">完整轮动结果</a> · <a href="rotation_backtest.py">复现程序</a> · <a href="README_rotation.md">说明</a> · <a href="../skhy_report3_all6_time_decay.html">报告3</a></p></section></main>'''
js=r'''
const $=id=>document.getElementById(id), fmt=(v,n=2)=>v==null?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}), money=v=>'$'+fmt(v), dt=s=>s?s.slice(5,16).replace('T',' '):'—', pc=v=>fmt(v)+'%', color=v=>v>=0?'pos':'neg';
const colors=['#58dcc0','#54afff','#ffd166','#e69dff','#ff8d70','#d4e46b'];
const table=(heads,rows)=>'<table><thead><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
const best=D.results.find(r=>r.id===D.best);$('asof').textContent=`行情区间 ${D.start} 至 ${D.end}｜每次1 Call＋1 Put｜无重叠持仓｜费用上限12%`;
$('cards').innerHTML=[['当前区间最高合计',money(best.stats.total)],['对应方案',best.name],['已实现／未实现',money(best.stats.realized)+' / '+money(best.stats.floating)],['该方案开仓次数',best.stats.positions]].map(([a,b])=>`<div class="card">${a}<strong>${b}</strong></div>`).join('');
$('conclusion').innerHTML=`<p>当前六方案中，<strong>${best.name}</strong>合计毛收益最高，为<strong>${money(best.stats.total)}</strong>；已平仓${best.stats.closed}笔，其中${best.stats.wins}笔盈利。请同时看回撤、总支出和未平仓估值，不能只按单笔盈利百分比判断期限性价比。</p><p>这套方案${best.stats.positions}笔中有${best.trades.filter(t=>t.decision.choice==='far').length}笔选择下周五、${best.trades.filter(t=>t.decision.choice==='near').length}笔选择本周五；最大单笔亏损${money(Math.max(0,-Math.min(...best.trades.map(t=>t.gross))))}，观察点最大回撤${money(best.stats.observed_drawdown)}。各灵活方案选择下周五的次数：${D.results.filter(r=>r.ratio||r.id==='sqrt').map(r=>r.name+' '+r.trades.filter(t=>t.decision.choice==='far').length+'次').join('；')}。若两档选择路径相同，收益也会相同。</p><p>本报告比较的是六种轮动期限规则，没有重做与报告3完全相同成交口径的非轮动对照；当前结果不能证明轮动一定优于原每周开仓策略。</p>`;
if(D.example){let e=D.example;let rows=Object.entries(e.candidates).map(([k,q])=>[k==='near'?'本周五':'下周五',q.expiry,fmt(q.strike),fmt(q.stock),fmt(q.dte,2),fmt(q.call),fmt(q.put),money(q.cost),pc(q.pct),q.pct<=12?'符合上限':'过贵']);$('example').innerHTML=`<p>报告3在${dt(e.previous_exit)}平仓，毛收益${money(e.previous_gross)}。按轮动规则，于${dt(e.strike_selection_time)}重新选约；以下费用比较使用${dt(e.decision_time)}当时已完成的成交分钟价。</p>`+table(['期限','到期','行权价','观察股价','剩余自然日','Call报价','Put报价','组合费用','费用／股价','12%上限'],rows)+`<p>${e.choices.map(x=>x.name+'：'+(x.expiry||'轮空')).join('；')}。</p><p class="muted">这是从报告3平仓点出发的独立选约示例，不是六条轮动路径新增的一笔收益；真实轮动此前已重开过仓，路径可能不同。上述为决策时估计费用，不保证下一共同成交分钟仍为同价。</p>`}else{$('example').textContent='暂无独立选约示例。'}
const rules={near:'周一至周四只买本周五；周五改买下周五。对应期限过贵则轮空。',far:'只买下周五；不回退到本周五。',ratio10:'两期限均合格时，下周费用≤本周×1.10则买下周，否则本周。',ratio25:'两期限均合格时，下周费用≤本周×1.25则买下周，否则本周。',ratio50:'两期限均合格时，下周费用≤本周×1.50则买下周，否则本周。',sqrt:'合格期限中，（权利金／股价）÷√剩余自然日最低者优先。'};
$('comparison').innerHTML=table(['方案','期限规则（均有12%上限）','合计毛收益','已实现','持仓估值盈亏','开仓／平仓','盈利笔数','轮空次数','累计权利金','最低现金需求','观察点最大回撤'],[...D.results].sort((a,b)=>b.stats.total-a.stats.total).map(r=>{let s=r.stats;return[r.name,`<div class="wrap">${rules[r.id]}</div>`,`<b class="${color(s.total)}">${money(s.total)}</b>`,money(s.realized),money(s.floating),s.positions+' / '+s.closed,s.wins,s.skips,money(s.premium_turnover),money(s.required_cash),money(s.observed_drawdown)]}));
$('quality').innerHTML=table(['方案','超过费用上限','缺少新鲜报价','无合格共同成交分钟','有两期限报价的决策次数'],D.results.map(r=>{let skips=r.decisions.filter(x=>x.action==='轮空');return[r.name,skips.filter(x=>x.reason.includes('超过12%')).length,skips.filter(x=>x.reason.includes('新鲜')).length,skips.filter(x=>x.reason.includes('共同成交')).length,r.decisions.filter(x=>x.candidates.near&&x.candidates.far).length]}));
$('legend').innerHTML=D.results.map((r,i)=>`<span style="color:${colors[i]}">${r.name}</span>`).join('');
$('policy').innerHTML=D.results.map(r=>`<option value="${r.id}">${r.name}</option>`).join('');$('policy').value=D.best;
let current=best,trade=best.trades[0];
function choose(){current=D.results.find(r=>r.id===$('policy').value);$('ledger').innerHTML=table(['笔次','买入时间','买入股价／行权价','到期日','卖出或估值时间','卖出或估值股价','Call买→卖','Put买→卖','支付权利金','收回／估值','毛盈亏','收益率','状态／触发'],current.trades.map(t=>[t.id,dt(t.entry.time),fmt(t.entry.stock)+' / '+fmt(t.contract.strike),t.contract.expiry,dt(t.exit.time),fmt(t.exit.stock),fmt(t.entry.call)+' → '+fmt(t.exit.call),fmt(t.entry.put)+' → '+fmt(t.exit.put),money(t.entry.value),money(t.exit.value),`<b class="${color(t.gross)}">${money(t.gross)}</b>`,pc(t.roi),`<div class="wrap">${t.status}${t.signal?'；'+t.signal.side+'目标'+pc(t.signal.target)+'，触发 '+dt(t.signal.time):''}</div>`]));
$('trade').innerHTML=current.trades.map((t,i)=>`<option value="${i}">第${t.id}笔：${dt(t.entry.time)} → ${dt(t.exit.time)} · ${money(t.gross)}</option>`).join('');
$('decisions').innerHTML=table(['观察时间','选行权价时间','本周五：到期／K／天数','本周费用／费用比','下周五：到期／K／天数','下周费用／费用比','下周加价','选择或轮空原因'],current.decisions.map(x=>{let a=x.candidates.near,b=x.candidates.far;let term=q=>q?q.expiry+' / '+fmt(q.strike)+' / '+fmt(q.dte,1)+'天':'—';let price=q=>q?money(q.cost)+' / '+pc(q.pct):'—';return[dt(x.time),dt(x.strike_selection_time),term(a),price(a),term(b),price(b),a&&b?pc((b.premium/a.premium-1)*100):'—',`<div class="wrap">${x.action==='开仓'?('开仓 '+x.expiry):('轮空：'+x.reason)}</div>`]}));chooseTrade()}
function chooseTrade(){trade=current.trades[+$('trade').value||0];if(!trade){$('tradeinfo').textContent='此方案无交易';return;}let t=trade;$('tradeinfo').innerHTML=`<p>第${t.id}笔，K=${fmt(t.contract.strike)}，到期${t.contract.expiry}；入场股价${money(t.entry.stock)}，退出或估值股价${money(t.exit.stock)}。Call盈亏${money(t.call_pnl)}，Put盈亏${money(t.put_pnl)}，合计<strong>${money(t.gross)}</strong>。${t.exit.ages?'期末两腿价格年龄：Call '+t.exit.ages.call+'分钟，Put '+t.exit.ages.put+'分钟。':''}</p>`;drawTrade()}
let setups={};function chart(id,tip,series,dual=false){let c=$(id),rect=c.getBoundingClientRect(),w=rect.width,h=420,dpr=devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);let pad={l:70,r:dual?65:25,t:20,b:40};let flat=series.flatMap(s=>s.points),xs=flat.map(p=>Date.parse(p.time));if(!xs.length)return;let xmin=Math.min(...xs),xmax=Math.max(...xs);if(xmax===xmin)xmax+=60000;let ranges=[0,1].map(axis=>{let v=series.filter(s=>(s.axis||0)===axis).flatMap(s=>s.points.map(p=>p.value));let lo=Math.min(0,...v),hi=Math.max(0,...v);if(hi===lo)hi=lo+1;let z=(hi-lo)*.08;return[lo-z,hi+z]});let X=x=>pad.l+(x-xmin)/(xmax-xmin)*(w-pad.l-pad.r),Y=(v,axis=0)=>h-pad.b-(v-ranges[axis][0])/(ranges[axis][1]-ranges[axis][0])*(h-pad.t-pad.b);
ctx.font='11px system-ui';ctx.textAlign='right';for(let i=0;i<6;i++){let v=ranges[0][0]+(ranges[0][1]-ranges[0][0])*i/5,y=Y(v);ctx.strokeStyle='#293445';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillStyle='#9cabbe';ctx.fillText(fmt(v,0),pad.l-8,y+4)}if(dual){ctx.textAlign='left';for(let i=0;i<6;i++){let v=ranges[1][0]+(ranges[1][1]-ranges[1][0])*i/5;ctx.fillStyle='#54afff';ctx.fillText(fmt(v,1)+'%',w-pad.r+6,Y(v,1)+4)}}
for(let a=0;a<(dual?2:1);a++){ctx.setLineDash(a?[3,5]:[9,5]);ctx.strokeStyle=a?'#54afff':'#58dcc0';ctx.beginPath();ctx.moveTo(pad.l,Y(0,a));ctx.lineTo(w-pad.r,Y(0,a));ctx.stroke()}ctx.setLineDash([]);ctx.textAlign='center';for(let i=0;i<6;i++){let x=xmin+(xmax-xmin)*i/5;ctx.fillStyle='#9cabbe';ctx.fillText(new Date(x).toLocaleDateString('en-US',{timeZone:'America/New_York',month:'2-digit',day:'2-digit'}),X(x),h-12)}
for(let s of series){ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();s.points.forEach((p,i)=>{let x=X(Date.parse(p.time)),y=Y(p.value,s.axis||0);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
setups[id]={series,xmin,xmax,w,pad,tip};c.onmousemove=e=>{let z=setups[id],xx=e.clientX-c.getBoundingClientRect().left,target=z.xmin+(xx-z.pad.l)/(z.w-z.pad.l-z.pad.r)*(z.xmax-z.xmin);let lines=z.series.map(s=>{let p=s.points.filter(p=>Date.parse(p.time)<=target).at(-1)||s.points[0];return`<div style="color:${s.color}">${s.name}：${fmt(p.value)}${s.axis?'%':'$'} <small>${dt(p.time)}</small></div>`});$(tip).innerHTML=lines.join('');$(tip).style.display='block';$(tip).style.left=Math.max(0,Math.min(xx+14,w-340))+'px';$(tip).style.top='25px'};c.onmouseleave=()=>$(tip).style.display='none';}
function drawEquity(){chart('equity','equitytip',D.results.map((r,i)=>({name:r.name,color:colors[i],points:r.equity})))}
function drawTrade(){if(!trade)return;let t=trade,pts=[{time:t.entry.time,pnl:0,stock:t.entry.stock},...t.curve,{time:t.exit.time,pnl:t.gross,stock:t.exit.stock}];chart('tradechart','tradetip',[{name:'组合毛收益',color:'#58dcc0',points:pts.map(p=>({time:p.time,value:p.pnl}))},{name:'股票涨跌',color:'#54afff',axis:1,points:pts.map(p=>({time:p.time,value:(p.stock/t.entry.stock-1)*100}))}],true)}
$('policy').onchange=choose;$('trade').onchange=chooseTrade;choose();drawEquity();window.addEventListener('resize',()=>{drawEquity();drawTrade()});
'''
